// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/cli/start", wrapper.CliStart)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/web/start", wrapper.WebStart)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/auth/google/callback", wrapper.GoogleCallback)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/cli/exchange", wrapper.CliExchange)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/auth/token", wrapper.RevokeOwnToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.WebLogout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/ingest", wrapper.Ingest)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sessions/{sessionId}/summary", wrapper.SetSessionSummary)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/usage", wrapper.GetMyUsage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/sessions", wrapper.ListMySessions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/by-login", wrapper.AdminByLogin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/by-account", wrapper.AdminByAccount)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/accounts", wrapper.AdminListAccounts)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/admin/accounts/{id}", wrapper.AdminUpdateAccount)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/users", wrapper.AdminListUsers)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/users/{id}/sessions", wrapper.AdminListUserSessions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/tokens", wrapper.AdminListTokens)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/admin/tokens/{id}", wrapper.AdminRevokeToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/admin/prices", wrapper.AdminListPrices)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/admin/prices/{model}", wrapper.AdminPutPrice)

	return m
}
